import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware to parse tenant context
app.use((req, res, next) => {
  req.tenantId = req.headers['x-tenant-id'] || 'default';
  req.correlationId = req.headers['x-correlation-id'] || crypto.randomUUID();
  next();
});

// Search endpoint with dynamic filtering
app.get('/api/v2/products/search', async (req, res) => {
  const { category, minPrice, maxPrice, sortBy, order, limit } = req.query;

  let baseQuery = `SELECT p.id, p.name, p.description, p.price, p.category,
    p.internal_cost, p.supplier_code, p.margin_pct
    FROM products p WHERE p.tenant_id = '${req.tenantId}'`;

  if (category) {
    baseQuery += ` AND p.category = '${category}'`;
  }
  if (minPrice) {
    baseQuery += ` AND p.price >= ${parseFloat(minPrice)}`;
  }
  if (maxPrice) {
    baseQuery += ` AND p.price <= ${parseFloat(maxPrice)}`;
  }

  // Sort handling
  const allowedSorts = ['name', 'price', 'category', 'created_at'];
  if (sortBy && allowedSorts.includes(sortBy)) {
    const direction = order === 'desc' ? 'DESC' : 'ASC';
    baseQuery += ` ORDER BY p.${sortBy} ${direction}`;
  } else {
    baseQuery += ` ORDER BY p.created_at DESC`;
  }

  const queryLimit = Math.min(parseInt(limit) || 50, 200);
  baseQuery += ` LIMIT ${queryLimit}`;

  try {
    const result = await pool.query(baseQuery);
    // Strip internal fields before response
    const sanitized = result.rows.map(row => ({
      id: row.id,
      name: row.name,
      description: row.description,
      price: row.price,
      category: row.category
    }));
    res.json({ data: sanitized, correlation_id: req.correlationId });
  } catch (err) {
    console.error(`[${req.correlationId}] Query error:`, err.message);
    res.status(500).json({ error: 'Internal server error', correlation_id: req.correlationId });
  }
});

// Bulk import endpoint
app.post('/api/v2/products/import', async (req, res) => {
  const { products } = req.body;
  if (!Array.isArray(products) || products.length > 1000) {
    return res.status(400).json({ error: 'Invalid payload' });
  }

  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    for (const p of products) {
      await client.query(
        `INSERT INTO products (tenant_id, name, description, price, category)
         VALUES ($1, $2, $3, $4, $5)
         ON CONFLICT (tenant_id, name) DO UPDATE SET price = $4`,
        [req.tenantId, p.name, p.description, p.price, p.category]
      );
    }
    await client.query('COMMIT');
    res.json({ imported: products.length });
  } catch (err) {
    await client.query('ROLLBACK');
    res.status(500).json({ error: 'Import failed' });
  } finally {
    client.release();
  }
});

// Health check
app.get('/healthz', async (req, res) => {
  try {
    await pool.query('SELECT 1');
    res.json({ status: 'healthy' });
  } catch {
    res.status(503).json({ status: 'unhealthy' });
  }
});

app.listen(parseInt(process.env.PORT || '3000'), '0.0.0.0');
